clear; awk '
$0 ~ /^\[$/ { n=0; next }
{ n++; line[n]=$0 }
n==8 {
  ts=line[2]; orig=line[3]; type=line[4]; code=line[5]; len=line[7]
  gsub(/^[ \t"]+|[ \t"]+$/, "", ts); gsub(/^[ \t"]+|[ \t"]+$/, "", orig)
  gsub(/^[ \t"]+|[ \t"]+$/, "", type); gsub(/^[ \t"]+|[ \t"]+$/, "", code)
  gsub(/^[ \t"]+|[ \t"]+$/, "", len)
  if (orig ~ /2\.2/ && len+0 > 100000) print code, len, ts, orig
  n=0
}' /tmp/cdxfields.txt | sort -k2,2rn | head -40

